import { policyActions, economicVariables, policyEffects, diagramData } from '../data/economicData';

export const getRandomQuestion = () => {
  // 随机生成一个问题
  const randomPolicy = policyActions[Math.floor(Math.random() * policyActions.length)];
  const randomVariable = economicVariables[Math.floor(Math.random() * economicVariables.length)];
  
  // 查找正确答案
  const effect = policyEffects.find(
    effect => effect.policyId === randomPolicy.id && effect.variableId === randomVariable.id
  );

  return {
    policy: randomPolicy.action,
    variable: randomVariable.name,
    correctAnswer: effect ? effect.effect : 'indeterminate',
    explanation: effect ? effect.explanation : '这种情况下的影响需要考虑多个因素'
  };
};

export const getDiagramQuestion = () => {
  // 随机生成一个图表相关的问题
  const randomDiagram = diagramData[Math.floor(Math.random() * diagramData.length)];
  const randomCurve = randomDiagram.curves[Math.floor(Math.random() * randomDiagram.curves.length)];
  
  return {
    diagram: randomDiagram.name,
    curve: randomCurve,
    // 这里可以添加更多逻辑
  };
};
